begin;
create table app.curriculum_behavior_acceptances(
 school_id uuid not null,id uuid not null default gen_random_uuid(),version_id uuid not null,lifecycle_revision integer not null,review_basis text not null check(review_basis in('SCHOOL_AUTHORED','LOCKED_ARTIFACT')),artifact_directory text,artifact_digest text,behavior jsonb not null,reason text not null check(length(btrim(reason))between 1 and 2000),accepted_by uuid not null,accepted_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,version_id,lifecycle_revision),foreign key(school_id,version_id,lifecycle_revision)references app.curriculum_lifecycle_revisions(school_id,version_id,revision),foreign key(school_id,accepted_by)references app.memberships(school_id,actor_id),check(jsonb_typeof(behavior)='object'),check((review_basis='SCHOOL_AUTHORED'and artifact_directory is null and artifact_digest is null)or(review_basis='LOCKED_ARTIFACT'and artifact_directory~'^[a-z0-9-]+$'and artifact_digest~'^[a-f0-9]{64}$'))
);
alter table app.curriculum_behavior_acceptances enable row level security;alter table app.curriculum_behavior_acceptances force row level security;revoke all on app.curriculum_behavior_acceptances from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
create trigger behavior_immutable before update or delete on app.curriculum_behavior_acceptances for each row execute function internal.academic_history_immutable();create trigger behavior_no_truncate before truncate on app.curriculum_behavior_acceptances for each statement execute function internal.academic_history_immutable();
create function internal.accept_curriculum_behavior(target_version uuid,payload jsonb,accepted_behavior jsonb,command_key text,fingerprint text,request_id text)returns jsonb language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();pack app.curriculum_versions;lifecycle app.curriculum_lifecycle_revisions;reservation jsonb;receipt jsonb;begin
 perform internal.require_curriculum_lifecycle(target_version,true);perform pg_advisory_xact_lock(hashtextextended(school::text||':curriculum-lifecycle',0));
 select*into pack from app.curriculum_versions where school_id=school and id=target_version;
 select*into lifecycle from app.curriculum_lifecycle_revisions where school_id=school and version_id=target_version order by revision desc limit 1;
 if payload is null or jsonb_typeof(payload)<>'object'or payload-'reviewBasis'-'artifactDirectory'-'expectedLifecycleRevision'-'reason'-'confirmAcceptance'<>'{}'::jsonb or payload->'confirmAcceptance'is distinct from'true'::jsonb or jsonb_typeof(payload->'reason')is distinct from'string'or length(btrim(payload->>'reason'))not between 1 and 2000 or lifecycle.revision is distinct from(payload->>'expectedLifecycleRevision')::integer or lifecycle.state not in('APPROVED','ACTIVE','SUPERSEDED')or not pack.synthetic or pack.kind<>'school_custom'or pack.source_status<>'VERIFIED'or pack.rights_status<>'PERMITTED'then raise exception 'Current reviewed behavior acceptance required'using errcode='22023';end if;
 if accepted_behavior is null or jsonb_typeof(accepted_behavior)<>'object'or accepted_behavior->>'basis'is distinct from payload->>'reviewBasis'or accepted_behavior->>'version'is distinct from pack.version or jsonb_typeof(accepted_behavior->'models')is distinct from'array'then raise exception 'Exact source behavior required'using errcode='22023';end if;
 if jsonb_array_length(accepted_behavior->'models')not between 1 and 2 or exists(select 1 from jsonb_array_elements_text(accepted_behavior->'models')model where model not in('numeric','rubric'))or payload->>'reviewBasis'='LOCKED_ARTIFACT'and(jsonb_typeof(accepted_behavior->'numericMaxScore')is distinct from'number'or(accepted_behavior->>'numericMaxScore')::numeric<=0 or(accepted_behavior->>'numericMaxScore')::numeric>100000 or jsonb_typeof(accepted_behavior->'rubric')is distinct from'object')then raise exception 'Native accepted model configuration invalid'using errcode='22023';end if;
 if payload->>'reviewBasis'='LOCKED_ARTIFACT'then
  if payload->>'artifactDirectory'is null or accepted_behavior->>'directory'is distinct from payload->>'artifactDirectory'or accepted_behavior->>'digest'is null or(lifecycle.artifact_digest is not null and accepted_behavior->>'digest'is distinct from lifecycle.artifact_digest)or accepted_behavior->>'packId'is distinct from pack.pack_id or accepted_behavior->>'framework'is distinct from pack.framework or accepted_behavior->>'programme'is distinct from pack.programme or accepted_behavior->>'scope'is distinct from pack.scope or accepted_behavior->>'sourceChecksum'is distinct from pack.source_checksum or jsonb_typeof(accepted_behavior->'references')is distinct from'array'then raise exception 'Locked accepted behavior provenance differs'using errcode='22023';end if;
  if jsonb_array_length(accepted_behavior->'references')<>(select count(*)from app.curriculum_references where school_id=school and pack_version_id=pack.id)or(select count(distinct source->>'title')from jsonb_array_elements(accepted_behavior->'references')source)<>jsonb_array_length(accepted_behavior->'references')or exists(select 1 from app.curriculum_references reference left join app.curriculum_references parent on parent.school_id=reference.school_id and parent.id=reference.parent_id where reference.school_id=school and reference.pack_version_id=pack.id and not exists(select 1 from jsonb_array_elements(accepted_behavior->'references')source where source->>'title'=reference.title and source->>'description'=reference.description and source->>'type'=reference.type and(source->>'sequence')::integer=reference.sequence and source->>'parentTitle'is not distinct from parent.title))then raise exception 'Accepted behavior hierarchy differs from locked source'using errcode='22023';end if;
  if not internal.valid_rubric_definition(accepted_behavior->'rubric'->'criteria')or length(btrim(accepted_behavior->'rubric'->>'title'))not between 1 and 200 or length(btrim(accepted_behavior->'rubric'->>'version'))not between 1 and 100 then raise exception 'Native rubric source definition invalid'using errcode='22023';end if;
 elsif payload->>'reviewBasis'='SCHOOL_AUTHORED'then if lifecycle.artifact_digest is not null or accepted_behavior->>'directory'is not null or accepted_behavior->>'digest'is not null then raise exception 'Locked context cannot downgrade to school declarations'using errcode='22023';end if;
 else raise exception 'Explicit behavior basis required'using errcode='22023';end if;
 reservation:=internal.begin_command(command_key,'curriculum.behavior.accept',fingerprint);if reservation->>'state'='COMPLETED'then return reservation->'response';end if;if reservation->>'state'<>'NEW'then raise exception 'Behavior acceptance in progress'using errcode='22023';end if;
 insert into app.curriculum_behavior_acceptances(school_id,version_id,lifecycle_revision,review_basis,artifact_directory,artifact_digest,behavior,reason,accepted_by)values(school,target_version,lifecycle.revision,payload->>'reviewBasis',payload->>'artifactDirectory',accepted_behavior->>'digest',accepted_behavior,payload->>'reason',"authorization".actor_id());receipt:=jsonb_build_object('id',target_version,'lifecycleRevision',lifecycle.revision);
 perform internal.append_audit('curriculum.behavior.accept','curriculum',target_version,request_id,'succeeded','{}');perform internal.enqueue_event('curriculum.configured','curriculum',target_version,lifecycle.revision,'{}',md5('curriculum-behavior:'||command_key));perform internal.finish_command(command_key,'curriculum.behavior.accept',fingerprint,receipt);return receipt;
end$$;
create function internal.read_course_curriculum_behavior(target_course uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();pack app.curriculum_versions;acceptance app.curriculum_behavior_acceptances;begin
 perform internal.require_course_objective_access(target_course,false);
 select version.*into pack from app.programme_course_contexts pinned join app.programme_instances programme on programme.school_id=pinned.school_id and programme.id=pinned.programme_id join app.curriculum_versions version on version.school_id=programme.school_id and version.id=programme.pack_version_id where pinned.school_id=school and pinned.course_id=target_course;
 if pack.id is null then return null;end if;
 select*into acceptance from app.curriculum_behavior_acceptances where school_id=school and version_id=pack.id order by lifecycle_revision desc limit 1;
 if acceptance.id is null then if exists(select 1 from app.curriculum_lifecycle_revisions where school_id=school and version_id=pack.id and artifact_digest is not null)then raise exception 'Explicit locked behavior receipt required'using errcode='22023';end if;return jsonb_build_object('basis','SCHOOL_AUTHORED','version',pack.version,'models',jsonb_build_array('numeric','rubric'),'numericMaxScore',null,'rubric',null,'directory',null,'digest',null);end if;
 return acceptance.behavior-'references'-'packId'-'sourceChecksum'-'framework'-'programme'-'scope';
end$$;
create function internal.read_curriculum_behavior_acceptance(target_version uuid)returns jsonb language plpgsql stable security definer set search_path=''as $$declare school uuid:="authorization".school_id();pack app.curriculum_versions;acceptance app.curriculum_behavior_acceptances;begin
 perform internal.require_curriculum_lifecycle(target_version,false);select*into pack from app.curriculum_versions where school_id=school and id=target_version;select*into acceptance from app.curriculum_behavior_acceptances where school_id=school and version_id=target_version order by lifecycle_revision desc limit 1;
 return jsonb_build_object('id',target_version,'lifecycleRevision',(select max(revision)from app.curriculum_lifecycle_revisions where school_id=school and version_id=target_version),'accepted',acceptance.id is not null,'basis',acceptance.review_basis,'behavior',acceptance.behavior-'references'-'packId'-'sourceChecksum','reason',acceptance.reason,'requiresReview',acceptance.id is null and exists(select 1 from app.curriculum_lifecycle_revisions where school_id=school and version_id=target_version and artifact_digest is not null));
end$$;
create function internal.accepted_assessment_behavior_guard()returns trigger language plpgsql security definer set search_path=''as $$declare pack uuid;acceptance app.curriculum_behavior_acceptances;begin
 select programme.pack_version_id into pack from app.programme_course_contexts pinned join app.programme_instances programme on programme.school_id=pinned.school_id and programme.id=pinned.programme_id where pinned.school_id=new.school_id and pinned.course_id=new.course_id;
 if pack is null then return new;end if;select*into acceptance from app.curriculum_behavior_acceptances where school_id=new.school_id and version_id=pack order by lifecycle_revision desc limit 1;
 if acceptance.id is null then if exists(select 1 from app.curriculum_lifecycle_revisions where school_id=new.school_id and version_id=pack and artifact_digest is not null)then raise exception 'Accepted locked model behavior missing'using errcode='22023';end if;return new;end if;
 if not(acceptance.behavior->'models'?new.model)or acceptance.review_basis='LOCKED_ARTIFACT'and new.model='numeric'and new.max_score<>(acceptance.behavior->>'numericMaxScore')::numeric or not(acceptance.behavior->'models'?new.intended_model)then raise exception 'Assessment native behavior differs from accepted source'using errcode='22023';end if;return new;
end$$;
create trigger accepted_assessment_behavior before insert or update on app.assessments for each row execute function internal.accepted_assessment_behavior_guard();
create function internal.accepted_rubric_behavior_guard()returns trigger language plpgsql security definer set search_path=''as $$declare course uuid;pack uuid;acceptance app.curriculum_behavior_acceptances;definition app.rubric_versions;begin
 if tg_table_name='rubric_versions'then course:=new.course_id;definition:=new;else select course_id into course from app.assessments where school_id=new.school_id and id=new.assessment_id;select*into definition from app.rubric_versions where school_id=new.school_id and id=new.rubric_id;end if;
 select programme.pack_version_id into pack from app.programme_course_contexts pinned join app.programme_instances programme on programme.school_id=pinned.school_id and programme.id=pinned.programme_id where pinned.school_id=new.school_id and pinned.course_id=course;
 select*into acceptance from app.curriculum_behavior_acceptances where school_id=new.school_id and version_id=pack order by lifecycle_revision desc limit 1;
 if acceptance.id is null and pack is not null and exists(select 1 from app.curriculum_lifecycle_revisions where school_id=new.school_id and version_id=pack and artifact_digest is not null)then raise exception 'Accepted locked rubric behavior missing'using errcode='22023';end if;
 if acceptance.id is not null and acceptance.review_basis='LOCKED_ARTIFACT'and jsonb_build_object('title',definition.title,'version',definition.version,'criteria',definition.criteria)is distinct from acceptance.behavior->'rubric'then raise exception 'Rubric definition differs from accepted native source'using errcode='22023';end if;return new;
end$$;
create trigger accepted_rubric_behavior before insert on app.rubric_versions for each row execute function internal.accepted_rubric_behavior_guard();create trigger accepted_assessment_rubric_behavior before insert on app.assessment_rubrics for each row execute function internal.accepted_rubric_behavior_guard();
revoke execute on function internal.accept_curriculum_behavior(uuid,jsonb,jsonb,text,text,text),internal.read_course_curriculum_behavior(uuid),internal.read_curriculum_behavior_acceptance(uuid),internal.accepted_assessment_behavior_guard(),internal.accepted_rubric_behavior_guard()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.accept_curriculum_behavior(uuid,jsonb,jsonb,text,text,text),internal.read_course_curriculum_behavior(uuid),internal.read_curriculum_behavior_acceptance(uuid)to cuevo_api;
commit;
